<!DOCTYPE html>
<html>
<head>
<style>
body {
  margin: 0;
  padding: 5px;
  background: linear-gradient(135deg, 
    var(--bg-gradient-1) 0%, 
    var(--bg-gradient-2) 35%, 
    var(--bg-gradient-3) 100%);
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
}

.status-wrapper {
  color: var(--text-primary);
  font-family: 'Malgun Gothic', '맑은 고딕', sans-serif;
  padding: 16px;
  max-width: 500px;
  width: 100%;
  margin: 5px auto;

  background: var(--bg-secondary);
  border: 1px solid var(--border-subtle);
  border-radius: 16px;
  box-shadow: 
    0 8px 32px var(--shadow-soft),
    0 2px 8px rgba(0, 0, 0, 0.05),
    inset 0 1px 0 var(--highlight-color);

  background-image: 
    radial-gradient(circle at 20% 20%, var(--accent-glow) 0%, transparent 50%),
    radial-gradient(circle at 80% 80%, rgba(244, 123, 123, 0.03) 0%, transparent 50%);

  font-size: 13px;
  line-height: 1.4;
  position: relative;

  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
}

.status-wrapper::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 1px;
  background: linear-gradient(90deg, 
    transparent 0%, 
    var(--highlight-color) 50%, 
    transparent 100%);
  border-radius: 16px 16px 0 0;
}

.username {
  color: var(--text-title);
  font-size: 20px;
  font-weight: 700;
  margin: 0 0 10px 0;
  text-shadow: 0 1px 2px rgba(0, 0, 0, 0.1);
}

.info-line {
  margin: 4px 0;
  font-size: 12px;
  color: var(--text-secondary);
  padding: 4px 8px;
  background: var(--bg-tertiary);
  border-radius: 8px;
  border: 1px solid var(--highlight-color);
}

.info-line strong {
  font-weight: 600;
  color: var(--text-primary);
  margin-right: 8px;
}

.info-line[data-content=""] {
  display: none;
}

.user-quote {
  font-style: italic;
  color: var(--text-secondary);
  text-align: center;
  padding: 8px 12px;
  margin: 8px 0;
  font-size: 13px;
  background: var(--bg-primary);
  border-radius: 12px;
  border-left: 3px solid var(--favor-neutral);
  position: relative;

  background-image: linear-gradient(135deg, 
    rgba(244, 123, 123, 0.02) 0%, 
    transparent 50%);
}

.user-quote::before,
.user-quote::after {
  content: '"';
  font-size: 18px;
  color: var(--text-tertiary);
  opacity: 0;
}

.timestamp {
  font-size: 11px;
  color: var(--text-tertiary);
  text-align: right;
  margin-bottom: 10px;
  white-space: nowrap;
  padding: 4px 8px;
  background: var(--timestamp-bg);
  border-radius: 6px;
  display: inline-block;
  margin-left: auto;
  width: fit-content;
}

.char-list {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin-top: 5px;
}

.char-item {
  display: grid;
  grid-template-columns: 1fr auto;
  grid-template-rows: auto auto auto;
  align-items: center;
  gap: 0px 10px;
  padding: 8px;
  background: var(--bg-tertiary);
  border-radius: 10px;
  border: 1px solid var(--border-subtle);
  transition: all 0.2s ease;
  position: relative;
  overflow: hidden;
}

.char-item::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 2px;
  background: linear-gradient(90deg, 
    var(--favor-neutral) 0%, 
    transparent 100%);
  opacity: 0.6;
  transition: background 0.3s ease;
}

.char-item:hover {
  background: var(--bg-hover);
  border-color: var(--border-hover);
  transform: translateY(-1px);
}

.char-item[data-content=""] {
  display: none;
}

.char-name-icon {
  grid-column: 1 / 2;
  font-weight: bold;
  font-size: 14px;
  white-space: nowrap;
  text-shadow: 0 1px 2px rgba(0, 0, 0, 0.05);
}

.char-favor {
  grid-column: 2 / 3;
  justify-self: end;
  font-weight: bold;
  font-size: 13px;
  white-space: nowrap;
  padding: 4px 8px;
  border-radius: 6px;
  background: var(--timestamp-bg);
  transition: all 0.3s ease;
}

.char-status {
  grid-column: 1 / 3;
  color: var(--text-secondary);
  font-size: 12px;
  padding-top: 2px;
  padding-left: 4px;
  border-top: 1px solid var(--highlight-color);
  margin-top: 2px;
}

.char-location {
  grid-column: 1 / 3;
  color: var(--text-tertiary);
  font-size: 11px;
  padding-left: 4px;
  margin-top: 2px;
}

.char-location::before {
  content: '📍 ';
  opacity: 0.7;
}

.favor-symbol {
  margin-right: 2px;
  font-size: 14px;
}
details.status-fold {
  margin: 5px auto;
  max-width: 500px;
  width: 100%;
}

details.status-fold > summary {
  cursor: pointer;
  list-style: none;
  padding: 8px 14px;
  font-size: 13px;
  font-weight: 600;
  color: var(--text-primary);
  background: var(--bg-secondary);
  border: 1px solid var(--border-subtle);
  border-radius: 12px;
  user-select: none;
}

details.status-fold > summary::-webkit-details-marker {
  display: none;
}

details.status-fold > summary::before {
  content: "▶";
  font-size: 0.7em;
  margin-right: 8px;
  display: inline-block;
  transition: transform 0.2s ease;
}

details.status-fold[open] > summary::before {
  transform: rotate(90deg);
}
</style>
</head>
